package data

import "fmt"

type lessonInsight struct {
	core     string
	scenario string
	pitfall  string
	exercise string
	decision string
}

func insight(core, scenario, pitfall, exercise, decision string) lessonInsight {
	return lessonInsight{core: core, scenario: scenario, pitfall: pitfall, exercise: exercise, decision: decision}
}

func materialFor(title, objective string) LessonMaterial {
	item, ok := lessonInsights[title]
	if !ok {
		panic("missing detailed lesson material: " + title)
	}
	overview := fmt.Sprintf(
		"%s không chỉ là một thao tác kỹ thuật riêng lẻ. Trong dự án thật, quyết định liên quan đến chủ đề này ảnh hưởng trực tiếp tới khả năng bảo trì, tốc độ xử lý sự cố và mức độ an toàn khi thay đổi hệ thống. %s",
		title, item.core,
	)
	concepts := fmt.Sprintf(
		"%s\n\nĐiểm cần ghi nhớ là: %s. Khi đánh giá một implementation, cần kiểm tra dữ liệu đầu vào, đường đi của dữ liệu, hành vi khi dependency thất bại và cách quan sát kết quả. Một giải pháp tốt phải giải thích được vì sao nó phù hợp với tải hiện tại, cách nó thay đổi khi quy mô tăng, và giới hạn nào cần được ghi rõ trong tài liệu.",
		item.core, item.decision,
	)
	scenario := fmt.Sprintf(
		"%s\n\nTrong tình huống này, nhóm phát triển cần đo trạng thái trước khi thay đổi, triển khai theo bước nhỏ và giữ đường rollback. Sau khi triển khai phải quan sát log, metric hoặc kết quả truy vấn liên quan thay vì chỉ dựa vào việc chương trình không báo lỗi. Quyết định cuối cùng cần được ghi lại cùng giả định để người bảo trì sau hiểu được bối cảnh.",
		item.scenario,
	)
	pitfalls := fmt.Sprintf(
		"%s\n\nMột lỗi phổ biến khác là áp dụng ví dụ học tập trực tiếp vào production mà thiếu timeout, giới hạn tài nguyên, validation hoặc test cho failure path. Cần ưu tiên tính đúng và khả năng quan sát trước tối ưu vi mô; nếu có trade-off, hãy đo bằng dữ liệu và mô tả rõ điều gì được chấp nhận.",
		item.pitfall,
	)
	exercise := fmt.Sprintf(
		"%s\n\nYêu cầu nộp gồm mã nguồn hoặc cấu hình có thể chạy lại, README mô tả giả định, ít nhất ba trường hợp kiểm tra và một đoạn ngắn giải thích lựa chọn kỹ thuật. Với trường hợp lỗi, ghi rõ tín hiệu nào giúp phát hiện và cách khôi phục mà không làm mất dữ liệu.",
		item.exercise,
	)
	return LessonMaterial{
		Overview: overview, Concepts: concepts, Scenario: scenario, Pitfalls: pitfalls, Exercise: exercise,
		Quiz: []QuizFact{
			{Question: fmt.Sprintf("Nhận định nào mô tả đúng nhất kiến thức cốt lõi của bài %q?", title), Correct: item.core, Wrong: [3]string{"Chỉ cần chạy được happy path", "Luôn tối ưu trước khi đo", "Không cần ghi lại giả định"}},
			{Question: fmt.Sprintf("Quyết định kỹ thuật quan trọng nhất khi áp dụng %q là gì?", title), Correct: item.decision, Wrong: [3]string{"Chọn công cụ có nhiều tính năng nhất", "Bỏ qua giới hạn hệ thống", "Triển khai một lần cho toàn bộ hệ thống"}},
			{Question: fmt.Sprintf("Rủi ro nào cần được tránh trong tình huống của bài %q?", title), Correct: item.pitfall, Wrong: [3]string{"Viết tài liệu ngắn gọn", "Đo kết quả sau triển khai", "Giữ phương án rollback"}},
			{Question: fmt.Sprintf("Bài thực hành nào kiểm chứng đúng mục tiêu %q?", objective), Correct: item.exercise, Wrong: [3]string{"Chỉ sao chép code mẫu", "Chỉ mô tả lý thuyết", "Bỏ qua trường hợp lỗi"}},
		},
	}
}

